    /**
     * Invokes protected action nodes without constructing an installation-backed action selector.
     */
    private function callNode(RunImplementationWorkflow $action, string $method, ...$arguments)
    {
        return (new \ReflectionMethod(RunImplementationWorkflow::class, $method))->invoke($action, ...$arguments);
    }

    /**
     * Creates an action with its normal property defaults but no external dependencies.
     */
    private function action() : RunImplementationWorkflow
    {
        return (new \ReflectionClass(RunImplementationWorkflow::class))->newInstanceWithoutConstructor();
    }

    /**
