    /**
     * Checks the existing-tag path never invokes the agent, verifies or mutates Jira.
     */
    public function testExistingTagRunsTestsDirectly() : void
    {
        $action = $this->getMockBuilder(RunImplementationWorkflow::class)
            ->disableOriginalConstructor()
            ->onlyMethods(['invokeAgentNode', 'verifyPersistedTestTag', 'addLabel', 'executeRunTestsNode'])
            ->getMock();
        $action->expects(self::never())->method('invokeAgentNode');
        $action->expects(self::never())->method('verifyPersistedTestTag');
        $action->expects(self::never())->method('addLabel');
        $action->expects(self::once())->method('executeRunTestsNode')->with('BDT_DEMO-123')->willReturn('verified');
        $this->callNode($action, 'processTicket', $this->ticket(), ['BDT_DEMO-123'], 'testing',
            $this->createMock(WorkflowRunLog::class), null);
    }

    /**
     * Exercises the real action factory/task path and waits for deferred test execution exactly once.
     */
    public function testRunTestIsScopedAndStreamFinishesBeforeWorkflowStep() : void
    {
        $finished = false;
        $workbench = $this->createMock(WorkbenchInterface::class);
        $app = $this->createMock(App::class);
        $workbench->method('getApp')->willReturn($app);
        $app->method('has')->willReturn(true);
        $runTest = $this->createMock(ActionInterface::class);
        $app->expects(self::once())->method('getAction')
            ->with(self::callback(static fn($selector) => $selector->toString() === 'axenox.BDT.RunTest'), null)
            ->willReturn($runTest);
        $runTest->expects(self::once())->method('handle')->willReturnCallback(
            function (TaskInterface $task) use (&$finished) {
                self::assertSame('@BDT_DEMO-123', $task->getParameter('tags'));
                self::assertFalse($task->hasParameter('feature'));
                self::assertFalse($task->hasParameter('behat_config'));
                self::assertFalse($finished);
                $result = new ResultMessageStream($task);
                $result->setMessageStreamGenerator(static function () use (&$finished) {
                    yield "1 scenario (1 passed)\n3 steps (3 passed)\n";
                    $finished = true;
                    yield '===== Behat finished: all scenarios passed. =====';
                });
                return $result;
            }
        );
        $action = $this->getMockBuilder(RunImplementationWorkflow::class)
            ->disableOriginalConstructor()->onlyMethods(['getWorkbench'])->getMock();
        $action->method('getWorkbench')->willReturn($workbench);
        $log = $this->createMock(WorkflowRunLog::class);
        $log->expects(self::once())->method('finishStep')
            ->willReturnCallback(function ($step, $status) use (&$finished) {
                if ($status === WorkflowRunLog::STATUS_COMPLETED) {
                    self::assertTrue($finished);
                }
            });
        $output = $this->callNode($action, 'runStep', $log, 'run_tests', 'action', null, 'DEMO-123',
            fn() => $this->callNode($action, 'executeRunTestsNode', 'BDT_DEMO-123'));
        self::assertTrue($finished);
        self::assertStringContainsString('3 steps (3 passed)', $output);
    }

    /**
     * Requires creation, saved-tag verification, Jira association and execution in that order.
     */
    public function testMissingTagGeneratesAssociatesAndRuns() : void
    {
        $events = [];
        $action = $this->getMockBuilder(RunImplementationWorkflow::class)
            ->disableOriginalConstructor()
            ->onlyMethods(['invokeAgentNode', 'verifyPersistedTestTag', 'addLabel', 'executeRunTestsNode'])
            ->getMock();
        $response = $this->createMock(AiResponseInterface::class);
        $action->expects(self::once())->method('invokeAgentNode')
            ->willReturnCallback(function ($name, $alias, $ticket, $instruction) use (&$events, $response) {
                self::assertSame('test', $name);
                self::assertStringContainsString('@BDT_DEMO-123', $instruction);
                self::assertStringContainsString('Do not execute tests', $instruction);
                $events[] = 'agent';
                return $response;
            });
        $action->expects(self::once())->method('verifyPersistedTestTag')->with('BDT_DEMO-123')
            ->willReturnCallback(function () use (&$events) { $events[] = 'verify'; });
        $action->expects(self::once())->method('addLabel')->with('DEMO-123', 'BDT_DEMO-123')
            ->willReturnCallback(function () use (&$events) { $events[] = 'label'; });
        $action->expects(self::once())->method('executeRunTestsNode')->with('BDT_DEMO-123')
            ->willReturnCallback(function () use (&$events) { $events[] = 'run'; return 'verified'; });
        $this->callNode($action, 'processTicket', $this->ticket(), ['unrelated', 'BDT_DEMO-1234'], 'testing',
            $this->createMock(WorkflowRunLog::class), null);
        self::assertSame(['agent', 'verify', 'label', 'run'], $events);
    }

    /**
     * Never advertises or executes a feature the agent failed to save.
     */
    public function testMissingPersistedTagStopsBeforeJiraMutation() : void
    {
        $action = $this->getMockBuilder(RunImplementationWorkflow::class)
            ->disableOriginalConstructor()
            ->onlyMethods(['invokeAgentNode', 'verifyPersistedTestTag', 'addLabel', 'executeRunTestsNode'])
            ->getMock();
        $action->method('invokeAgentNode')->willReturn($this->createMock(AiResponseInterface::class));
        $action->method('verifyPersistedTestTag')->willThrowException(new \RuntimeException('No tagged feature'));
        $action->expects(self::never())->method('addLabel');
        $action->expects(self::never())->method('executeRunTestsNode');
        $this->expectExceptionMessage('No tagged feature');
        $this->callNode($action, 'processTicket', $this->ticket(), [], 'testing',
            $this->createMock(WorkflowRunLog::class), null);
    }

    /**
     * Keeps the original Ready route and does not execute browser tests during planning.
     */
    public function testReadyStillPlansRefreshesDesignsAndMarksReview() : void
    {
        $events = [];
        $ticket = $this->ticket('Ready');
        $action = $this->getMockBuilder(RunImplementationWorkflow::class)
            ->disableOriginalConstructor()
            ->onlyMethods(['invokeAgentNode', 'readTicketByKey', 'addLabel', 'executeRunTestsNode'])
            ->getMock();
        $response = $this->createMock(AiResponseInterface::class);
        $action->expects(self::exactly(2))->method('invokeAgentNode')
            ->willReturnCallback(function ($name) use (&$events, $response) { $events[] = $name; return $response; });
        $action->expects(self::once())->method('readTicketByKey')->with('DEMO-123')
            ->willReturnCallback(function () use (&$events, $ticket) { $events[] = 'refresh'; return $ticket; });
        $action->expects(self::once())->method('addLabel')->with('DEMO-123', 'AI_awaiting_review')
            ->willReturnCallback(function () use (&$events) { $events[] = 'review'; });
        $action->expects(self::never())->method('executeRunTestsNode');
        $this->callNode($action, 'processTicket', $ticket, [], 'ready', $this->createMock(WorkflowRunLog::class), null);
        self::assertSame(['story planner', 'refresh', 'test', 'review'], $events);
    }

