    /**
     * Includes Testing in discovery while retaining assignee and review-label guards.
     */
    public function testWorklistIncludesTesting() : void
    {
        $action = $this->getMockBuilder(RunImplementationWorkflow::class)
            ->disableOriginalConstructor()->onlyMethods(['requestJira'])->getMock();
        $action->expects(self::once())->method('requestJira')
            ->willReturnCallback(function ($method, $uri) {
                self::assertSame('GET', $method);
                parse_str(parse_url($uri, PHP_URL_QUERY), $query);
                self::assertStringContainsString('assignee = currentUser()', $query['jql']);
                self::assertStringContainsString('status IN ("Ready", "Implementing", "Testing")', $query['jql']);
                self::assertStringContainsString('labels NOT IN ("AI_awaiting_review")', $query['jql']);
                self::assertSame('100', $query['maxResults']);
                throw new \RuntimeException('Worklist inspected without contacting Jira');
            });
        $this->expectExceptionMessage('Worklist inspected without contacting Jira');
        $this->callNode($action, 'executeReadTicketsNode');
    }
